insert into public.narratives (case_id,narrative_key,version,status,author_agent,hook,short_setup,why_option_a_made_sense,why_option_b_made_sense,actual_decision_explanation,outcome_story,hindsight_analysis,decision_principle,longform_story,evidence_refs,quality_evaluations,revision_summary,is_current) values ((select id from public.decision_cases where case_key='challenger-1986'), 'challenger-1986', 1, 'APPROVED', 'codex-migration', 'Cold weather is outside your tested experience. The launch window is closing.', 'Engineers raised concern about O-ring performance in low temperatures.', 'Launch offered meet mission commitments, while accepting operate in poorly characterized cold.', 'Delay offered reduce untested exposure, while accepting schedule and reputational cost.', 'The historical actor selected Launch.', 'Challenger broke apart 73 seconds after launch; seven crew members died. The shuttle program paused and decision processes were investigated and reformed.', 'Schedule pressure and ambiguous evidence distorted how risk was communicated and accepted.', 'Absence of failure data is not evidence of safety outside the tested range.', 'Forecast temperatures are unusually low and engineers raise concerns about O-ring behavior.

Challenger broke apart 73 seconds after launch; seven crew members died.

The shuttle program paused and decision processes were investigated and reformed.', '["ch-e1","ch-e2","ch-e3"]'::jsonb, '{"migrated_fixture":{"status":"NEEDS_EDITORIAL_REVIEW"}}'::jsonb, 'Initial fixture migration.', true);

