insert into public.evidence (case_id,evidence_key,source_type,title,author_or_institution,publication_date,url,accessed_at,citation,evidence_class,supported_claim,source_quality,source_disagreement) values ((select id from public.decision_cases where case_key='netflix-2007'), 'nf-e1', 'company_press_release', 'Netflix Offers Subscribers the Option of Instantly Watching Movies on Their PCs', 'Netflix', '2007-01-16', 'https://about.netflix.com/en/news/netflix-offers-subscribers-the-option-of-instantly-watching-movies-on-their', '2026-08-30', null, 'FACT', 'Netflix introduced instant watching in a phased six-month rollout | The launch initially targeted personal computers | The service was added for subscribers rather than replacing DVDs immediately', 76, 25);

insert into public.evidence (case_id,evidence_key,source_type,title,author_or_institution,publication_date,url,accessed_at,citation,evidence_class,supported_claim,source_quality,source_disagreement) values ((select id from public.decision_cases where case_key='netflix-2007'), 'nf-e2', 'regulatory_filing', 'Netflix 2007 Form 10-K', 'Netflix / U.S. Securities and Exchange Commission', '2008-02-28', 'https://www.sec.gov/Archives/edgar/data/1065280/000119312508040378/d10k.htm', '2026-08-30', null, 'FACT', 'DVD subscriptions remained central in 2007 | Instant watching had been added to unlimited plans | Content licensing and exclusivity constrained streaming', 76, 25);

insert into public.evidence (case_id,evidence_key,source_type,title,author_or_institution,publication_date,url,accessed_at,citation,evidence_class,supported_claim,source_quality,source_disagreement) values ((select id from public.decision_cases where case_key='netflix-2007'), 'nf-e3', 'regulatory_filing', 'Netflix 2010 Form 10-K', 'Netflix / U.S. Securities and Exchange Commission', '2011-02-18', 'https://www.sec.gov/Archives/edgar/data/1065280/000119312511040217/d10k.htm', '2026-08-30', null, 'FACT', 'By the end of 2010 Netflix described itself as an Internet subscription streaming service | The company reported 20 million subscribers | Streaming depended on licensed content, cloud services, and connected devices', 76, 25);

insert into public.evidence (case_id,evidence_key,source_type,title,author_or_institution,publication_date,url,accessed_at,citation,evidence_class,supported_claim,source_quality,source_disagreement) values ((select id from public.decision_cases where case_key='netflix-2007'), 'nf-e4', 'editorial_method_note', 'Binary choice reconstruction note', 'Decision / T0 editorial review', '2026-08-30', null, '2026-08-30', null, 'INFERENCE', 'Invest now versus wait is an editorial compression of a phased investment decision, not a documented two-card executive vote', 76, 25);

insert into public.case_scores (case_id,curiosity,decision,stakes,mystery,explainability,evidence,player_fairness,dilemma_balance,context_compression,reveal_payoff,scorer,scoring_version,shorts_potential,notes) values ((select id from public.decision_cases where case_key='netflix-2007'), 82, 91, 83, 70, 93, 76, 83, 80, 84, 86, 'codex', '1.0', 83, 'Migrated unchanged from the local DecisionEvent fixture and narrative evaluation.');

insert into public.narratives (case_id,narrative_key,version,status,author_agent,hook,short_setup,why_option_a_made_sense,why_option_b_made_sense,actual_decision_explanation,outcome_story,hindsight_analysis,decision_principle,longform_story,evidence_refs,quality_evaluations,revision_summary,is_current) values ((select id from public.decision_cases where case_key='netflix-2007'), 'netflix-2007', 1, 'APPROVED', 'codex-migration', 'Your profitable product may be a bridge to its own replacement.', 'DVD-by-mail was working; streaming was immature.', 'Launching a limited streaming feature bought experience before the economics were settled. Netflix could observe demand, build delivery capability, and learn how licensing and user behavior differed from DVD rental. A phased rollout limited exposure. The downside was equally real: the catalog was constrained, viewing began on personal computers, licensing could be costly or exclusive, and investment could distract from a proven subscription-and-logistics business.', 'Waiting would protect attention and cash for the DVD service that customers already valued and that still generated the business. Better bandwidth, connected devices, codecs, and licensing terms might make a later launch cheaper and more compelling. But waiting also meant learning later. If internet delivery improved quickly, another platform could establish the customer relationship and technical ecosystem first.', 'Netflix launched instant watching in January 2007 through a phased rollout rather than replacing DVD-by-mail at once.', 'The first service offered a limited selection streamed to personal computers and was added gradually to subscriber plans. Over the next several years Netflix expanded content and device support. By the end of 2010, its annual filing described Netflix as an Internet subscription service streaming television and movies to 20 million subscribers, while DVDs still remained available in the United States. In later filings Netflix explicitly identified streaming growth as its core strategy.', 'The strong outcome does not prove every detail of the bet was knowable. The decision preserved strategic exposure to a plausible future. Its most defensible feature was not a heroic all-in prediction but the staged form of the launch: Netflix added a constrained learning channel beside the profitable DVD service. The product''s current A/B framing is an editorial compression, not evidence of a recorded executive vote between two cards. That distinction is important because production narrative must not invent a motive or meeting that the evidence does not establish.', 'When disruption is plausible, buy learning before certainty.', 'In January 2007, Netflix was not a failed company searching for rescue. Its DVD-by-mail subscription service was a working business built on distribution centers, recommendation software, and a large physical catalog. Streaming video, by contrast, arrived with obvious weaknesses: limited broadband capacity, a smaller licensable catalog, uneven playback, and viewing that initially centered on personal computers rather than televisions.

That is what makes the decision useful. The choice was not simply whether digital delivery sounded futuristic. It was whether to spend attention and resources on an inferior new channel while the existing one still worked. Waiting had a coherent logic. Device adoption and bandwidth could improve on their own. Studios might offer better rights later. Netflix could continue refining the service customers already paid for instead of funding an experience that looked worse on most dimensions.

Launching also had a coherent logic if it was treated as learning rather than replacement. Netflix announced an instant-watching feature on January 16, 2007 and said it would roll out to subscribers over six months. The limited start reduced the cost of being early. It exposed the company to real problems—delivery, interfaces, content rights, and viewing behavior—before those problems became the center of the business.

The evidence supports the launch and its phased character. It does not give us a transcript of one executive meeting in which leaders voted ''stream'' against ''wait.'' The product''s two options are therefore an editorial reconstruction of the strategic tradeoff. That reconstruction is acceptable only if the narrative labels it and avoids attributing undocumented beliefs to Reed Hastings or other executives.

The outcome unfolded over years. Netflix''s 2007 annual filing still described the economics and competitive constraints of content licensing while noting that unlimited-plan subscribers could use instant watching. By the end of 2010, the company reported 20 million subscribers and described itself as an Internet subscription service for streamed television and movies, even as it continued shipping DVDs in the United States. A subsequent filing called streaming growth the core strategy and described the DVD service as a fading differentiator.

It is tempting to turn that trajectory into a story of perfect foresight. The documents do not justify that. Streaming could have developed more slowly, licensing costs could have overwhelmed the model, and device fragmentation could have weakened the experience. The decision quality comes from acquiring a position and a learning loop without immediately destroying the profitable bridge that financed them.

The later success is a good outcome. It is not proof that every early streaming investment would have been good, or that waiting was irrational. The portable principle is narrower: when a plausible technology can replace the way value reaches customers, a staged experiment can be more valuable than either denial or an irreversible all-in commitment.', '["nf-e1","nf-e2","nf-e3","nf-e4"]'::jsonb, '{"PLAYER_FAIRNESS":{"score":83,"status":"PASS_WITH_CAVEAT","rationale":"Both strategic paths are supported, but the binary deliberation is editorially reconstructed rather than documented as a single vote."},"DILEMMA_BALANCE":{"score":80,"status":"PASS_WITH_CAVEAT","rationale":"The profitable DVD engine makes waiting credible; the phased rollout makes early learning credible. The current option label ''Invest now'' sounds more all-in than the actual launch."},"CONTEXT_COMPRESSION":{"score":84,"status":"PASS_WITH_CAVEAT","rationale":"The compression works if the UI or schema can label reconstructed strategic options."},"REVEAL_PAYOFF":{"score":86,"status":"PASS","rationale":"The reveal is the phased nature of the actual move and the documented shift in company description by 2010–2011, not merely that streaming later became large."}}'::jsonb, 'Initial fixture migration.', true);

insert into public.shorts_variants (case_id,narrative_id,version,status,author_agent,duration_target,script,storyboard,hook_variant) values ((select id from public.decision_cases where case_key='netflix-2007'), (select id from public.narratives where case_id=(select id from public.decision_cases where case_key='netflix-2007') and is_current limit 1), 1, 'APPROVED', 'codex-migration', '30_40', 'Your profitable product may be a bridge to its own replacement. DVD-by-mail was working; streaming was immature. Invest now vs Optimize DVDs Netflix launched instant watching in January 2007 through a phased rollout rather than replacing DVD-by-mail at once. Netflix launched Watch Now with a limited catalog and viewing restrictions.', '[{"at":"0-2","label":"HOOK","text":"Your profitable product may be a bridge to its own replacement."},{"at":"2-8","label":"CONTEXT","text":"DVD-by-mail was working; streaming was immature."},{"at":"8-13","label":"A/B","text":"Invest now vs Optimize DVDs"},{"at":"16-25","label":"ACTUAL DECISION","text":"Netflix launched instant watching in January 2007 through a phased rollout rather than replacing DVD-by-mail at once."},{"at":"25-32","label":"OUTCOME","text":"Netflix launched Watch Now with a limited catalog and viewing restrictions."}]'::jsonb, 'Your profitable product may be a bridge to its own replacement.');

