insert into public.case_scores (case_id,curiosity,decision,stakes,mystery,explainability,evidence,player_fairness,dilemma_balance,context_compression,reveal_payoff,scorer,scoring_version,shorts_potential,notes) values ((select id from public.decision_cases where case_key='new-coke-1985'), 86, 89, 75, 78, 96, 82, 91, 88, 87, 91, 'codex', '1.0', 84, 'Migrated unchanged from the local DecisionEvent fixture and narrative evaluation.');

insert into public.narratives (case_id,narrative_key,version,status,author_agent,hook,short_setup,why_option_a_made_sense,why_option_b_made_sense,actual_decision_explanation,outcome_story,hindsight_analysis,decision_principle,longform_story,evidence_refs,quality_evaluations,revision_summary,is_current) values ((select id from public.decision_cases where case_key='new-coke-1985'), 'new-coke-1985', 1, 'APPROVED', 'codex-migration', 'Taste tests say change. Identity says beware.', 'Blind taste tests favored a sweeter formula, while attachment to the original brand was harder to measure.', 'Replacing the formula acted on a large body of product evidence and presented one clear flagship rather than splitting marketing behind two versions. In a competitive cola market, a formula that performed better in blind sip tests appeared to address a visible weakness. The risk was that the tests measured taste under controlled conditions more directly than they measured what consumers believed Coca-Cola represented.', 'Keeping the original protected a century of accumulated identity and avoided forcing loyal customers to surrender a familiar product. Alternatives could still be tested as additions, regional releases, or limited trials. The downside was strategic hesitation: if taste really was driving competitive loss, preserving the formula could protect symbolism while allowing the underlying problem to continue.', 'Coca-Cola replaced its flagship formula with the new taste rather than keeping the original version alongside it at launch.', 'The company announced the formula change in April 1985. Consumer anger focused not only on the new taste but on the removal of the familiar product. After 79 days, Coca-Cola restored the original formula as Coca-Cola Classic while the new formula remained available under changing names for a time. The company recovered commercially, but the episode became a durable example of research that answered a narrower question than the decision required.', 'The research answered a narrower question than the decision required. Blind sip preference was relevant evidence, not worthless evidence. The mistake was allowing that result to stand in for a larger substitution decision involving identity, habit, symbolism, and loss. The mixed outcome also deserves care: the immediate launch produced backlash and reversal, while the company and original product recovered. That recovery does not retroactively make the replacement a clever plan, and the backlash does not mean every formula change would have been irrational.', 'Measure what customers are choosing—not only what they are tasting.', 'By 1985, Coca-Cola faced a competitive problem that seemed measurable. Pepsi had made taste comparison part of its challenge to the market leader, and Coca-Cola''s own testing found support for a sweeter formula. The evidence was not imaginary. In blind tasting conditions, many consumers preferred the proposed new product.

A leader looking only at that result could make a coherent argument for replacement. One flagship formula would concentrate production, advertising, and distribution behind the version that performed better in tests. A decisive change could show confidence and answer a rival''s most visible claim. Keeping the old formula, by contrast, risked treating heritage as a substitute for product performance.

But the decision was larger than the test. A sip comparison asks which liquid a participant prefers in a controlled moment. Replacing Coca-Cola asks whether customers accept losing a product bound to habit, memory, packaging, and national symbolism. Those are related questions, not identical ones. The option to retain the original did not require ignoring the taste data; the company could have introduced or tested an alternative without immediately removing the familiar formula.

Coca-Cola chose replacement. In April 1985 it announced the new taste and discontinued the old formula in its principal market. The reaction was intense. Consumers complained, organized, and demanded the old product back. Company histories acknowledge that the original formula returned after only 79 days, relaunched as Coca-Cola Classic. The new formula remained for a period and was later renamed, but it no longer carried the unquestioned position intended at launch.

The immediate outcome was bad for the replacement decision: backlash forced a rapid reversal. The longer outcome was mixed. Coca-Cola recovered, and renewed attachment to the original brand benefited Coca-Cola Classic. It would be a hindsight error to call the failed launch secretly successful merely because the company survived or later enjoyed stronger demand. There is no need to invent a hidden master plan to make the episode interesting.

Decision quality and outcome quality remain separate. The taste evidence made change understandable. What weakened the decision was the mismatch between the evidence collected and the action taken. A test of flavor preference carried more weight than it could bear when the actual move was the forced substitution of an identity-rich product.

The case remains difficult only if both sides receive their strongest argument. Replace, and you act on extensive product evidence in a competitive market. Retain, and you protect a form of customer value that ordinary blind testing may not capture. The principle is not ''never change an iconic product.'' It is to design research around the real decision—including what customers must give up—not around the easiest variable to isolate.', '["nc-e1","nc-e2","nc-e3","nc-e4"]'::jsonb, '{"PLAYER_FAIRNESS":{"score":91,"status":"PASS","rationale":"The player receives the positive taste evidence and the brand-attachment risk before choosing; the case does not depend on hiding obvious pre-launch information."},"DILEMMA_BALANCE":{"score":88,"status":"PASS","rationale":"Replacement acts on relevant evidence; retention protects a different form of value. Neither option is presented as foolish."},"CONTEXT_COMPRESSION":{"score":87,"status":"PASS","rationale":"The two options preserve the core replacement decision, though an ''introduce alongside'' option would improve fidelity in a future three-option schema."},"REVEAL_PAYOFF":{"score":91,"status":"PASS","rationale":"The 79-day reversal and mixed long-term outcome create a strong reveal while supporting the distinction between research quality, decision quality, and outcome."}}'::jsonb, 'Initial fixture migration.', true);

insert into public.shorts_variants (case_id,narrative_id,version,status,author_agent,duration_target,script,storyboard,hook_variant) values ((select id from public.decision_cases where case_key='new-coke-1985'), (select id from public.narratives where case_id=(select id from public.decision_cases where case_key='new-coke-1985') and is_current limit 1), 1, 'APPROVED', 'codex-migration', '30_40', 'Taste tests say change. Identity says beware. Blind taste tests favored a sweeter formula, while attachment to the original brand was harder to measure. Replace vs Retain Coca-Cola replaced its flagship formula with the new taste rather than keeping the original version alongside it at launch. Consumer backlash was intense; the original formula returned as Coca-Cola Classic after 79 days.', '[{"at":"0-2","label":"HOOK","text":"Taste tests say change. Identity says beware."},{"at":"2-8","label":"CONTEXT","text":"Blind taste tests favored a sweeter formula, while attachment to the original brand was harder to measure."},{"at":"8-13","label":"A/B","text":"Replace vs Retain"},{"at":"16-25","label":"ACTUAL DECISION","text":"Coca-Cola replaced its flagship formula with the new taste rather than keeping the original version alongside it at launch."},{"at":"25-32","label":"OUTCOME","text":"Consumer backlash was intense; the original formula returned as Coca-Cola Classic after 79 days."}]'::jsonb, 'Taste tests say change. Identity says beware.');

