insert into public.narratives (case_id,narrative_key,version,status,author_agent,hook,short_setup,why_option_a_made_sense,why_option_b_made_sense,actual_decision_explanation,outcome_story,hindsight_analysis,decision_principle,longform_story,evidence_refs,quality_evaluations,revision_summary,is_current) values ((select id from public.decision_cases where case_key='apollo-13-1970'), 'apollo-13-1970', 1, 'APPROVED', 'codex-migration', 'Your damaged spacecraft must become a lifeboat.', 'An oxygen tank explosion forced the crew and mission control to improvise with limited power and consumables.', 'Use the LM offered preserve return capability, while accepting overload a system designed for two people.', 'Stay in CM offered avoid complex transfer, while accepting rapidly exhaust vital resources.', 'The historical actor selected Use the LM.', 'The crew used the lunar module as a lifeboat and aborted the Moon landing. All three astronauts returned safely; the mission became a model of crisis problem-solving.', 'The response was strong because teams made constraints explicit, distributed expertise, and continuously revised the plan.', 'In a crisis, turn hidden constraints into a shared operating picture.', 'The command module is losing power and oxygen. The lunar module may keep the crew alive.

The crew used the lunar module as a lifeboat and aborted the Moon landing.

All three astronauts returned safely; the mission became a model of crisis problem-solving.', '["ap-e1","ap-e2","ap-e3"]'::jsonb, '{"migrated_fixture":{"status":"NEEDS_EDITORIAL_REVIEW"}}'::jsonb, 'Initial fixture migration.', true);

